-- Sales leads, follow-ups and their status masters for PostgreSQL.
BEGIN;
CREATE TABLE "LeadStatuses" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, "Id" UUID NOT NULL UNIQUE, "TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"), "Code" VARCHAR(40) NOT NULL, "Name" VARCHAR(120) NOT NULL, "DisplayOrder" INTEGER NOT NULL, "Color" VARCHAR(20), "IsClosed" BOOLEAN NOT NULL, "IsActive" BOOLEAN NOT NULL, "CreatedAtUtc" TIMESTAMPTZ NOT NULL, "UpdatedAtUtc" TIMESTAMPTZ NOT NULL, CONSTRAINT "UX_LeadStatuses_Tenant_Code" UNIQUE ("TenantId","Code"));
CREATE TABLE "FollowUpStatuses" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, "Id" UUID NOT NULL UNIQUE, "TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"), "Code" VARCHAR(40) NOT NULL, "Name" VARCHAR(120) NOT NULL, "DisplayOrder" INTEGER NOT NULL, "Color" VARCHAR(20), "IsCompleted" BOOLEAN NOT NULL, "IsActive" BOOLEAN NOT NULL, "CreatedAtUtc" TIMESTAMPTZ NOT NULL, "UpdatedAtUtc" TIMESTAMPTZ NOT NULL, CONSTRAINT "UX_FollowUpStatuses_Tenant_Code" UNIQUE ("TenantId","Code"));
CREATE TABLE "SalesLeads" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, "Id" UUID NOT NULL UNIQUE, "TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"), "LeadNumber" VARCHAR(40) NOT NULL, "CustomerName" VARCHAR(160) NOT NULL, "Phone" VARCHAR(40) NOT NULL, "Email" VARCHAR(254), "Source" VARCHAR(100), "MoveType" VARCHAR(80) NOT NULL, "Origin" VARCHAR(300) NOT NULL, "Destination" VARCHAR(300) NOT NULL, "ExpectedMoveDate" DATE, "StatusId" UUID NOT NULL REFERENCES "LeadStatuses"("Id"), "AssignedEmployeeId" UUID REFERENCES "Employees"("Id"), "Notes" VARCHAR(2000), "IsActive" BOOLEAN NOT NULL, "CreatedAtUtc" TIMESTAMPTZ NOT NULL, "UpdatedAtUtc" TIMESTAMPTZ NOT NULL, CONSTRAINT "UX_SalesLeads_Tenant_Number" UNIQUE ("TenantId","LeadNumber"));
CREATE INDEX "IX_SalesLeads_Tenant_Latest" ON "SalesLeads"("TenantId","SerialNo" DESC);
CREATE TABLE "LeadFollowUps" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, "Id" UUID NOT NULL UNIQUE, "TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"), "SalesLeadId" UUID NOT NULL REFERENCES "SalesLeads"("Id"), "ScheduledAtUtc" TIMESTAMPTZ NOT NULL, "StatusId" UUID NOT NULL REFERENCES "FollowUpStatuses"("Id"), "Notes" VARCHAR(2000) NOT NULL, "NextFollowUpAtUtc" TIMESTAMPTZ, "CreatedAtUtc" TIMESTAMPTZ NOT NULL, "UpdatedAtUtc" TIMESTAMPTZ NOT NULL);
CREATE INDEX "IX_LeadFollowUps_Lead_Latest" ON "LeadFollowUps"("SalesLeadId","SerialNo" DESC);
COMMIT;
